import { Gfx, PENCIL, type Ctx, type Env, rng } from "./core";
import { type Film } from "./film";
import { photoFields } from "./fromPhoto";

const W = 384, H = 682, FPS = 30, DURATION = 600; // 20 seconds for max detail!

export const drawBeeDetailed = (ctx: Ctx, frame: number, env: Env) => {
  const g = new Gfx(ctx, env, frame, PENCIL);
  const pf = photoFields(env, "bee");
  const r = rng(42); // deterministic

  ctx.setTransform(env.scale, 0, 0, env.scale, 0, 0);
  
  // Solid black background
  ctx.fillStyle = "#030303";
  ctx.fillRect(0, 0, W, H);

  const maxStrokes = 150000; // Massive detail increase
  const strokesToDraw = Math.floor((frame / DURATION) * maxStrokes);

  for (let i = 0; i < strokesToDraw; i++) {
    const px = Math.floor(r() * pf.iw);
    const py = Math.floor(r() * pf.ih);
    const idx = py * pf.iw + px;
    
    // Only draw where the original image is bright
    if (pf.lum[idx] > 0.05) {
      const pr = pf.r[idx] * 255;
      const pg = pf.g[idx] * 255;
      const pb = pf.b[idx] * 255;

      // Pass 1: Soft, glowing watercolor washes (first 40% of the strokes)
      if (i < maxStrokes * 0.4) {
        if (r() < 0.2) {
          ctx.beginPath();
          const rad = 2 + r() * 6;
          ctx.arc(px, py, rad, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${pr}, ${pg}, ${pb}, 0.08)`;
          ctx.fill();
        }
      } 
      // Pass 2: High-detail, crisp gold-foil structural lines
      else {
        const J11 = pf.J11[idx], J12 = pf.J12[idx], J22 = pf.J22[idx];
        const trace = J11 + J22;
        const det = J11 * J22 - J12 * J12;
        const l1 = trace / 2 + Math.sqrt(Math.max(0, trace * trace / 4 - det));
        let vx = J11 - l1, vy = J12;
        if (vx === 0 && vy === 0) { vx = J12; vy = J22 - l1; }
        const len = Math.hypot(vx, vy) || 1;
        vx /= len; vy /= len;

        const slen = 1 + r() * 4; // Shorter, more precise strokes
        
        ctx.beginPath();
        ctx.moveTo(px - vx * slen, py - vy * slen);
        ctx.lineTo(px + vx * slen, py + vy * slen);
        
        ctx.strokeStyle = `rgba(${pr}, ${pg}, ${pb}, ${0.4 + r() * 0.5})`;
        ctx.lineWidth = 0.3 + r() * 1.0; // Very fine details
        ctx.stroke();
      }
    }
  }
};

export const beeDetailedFilm: Film = {
  meta: { title: "Golden Bee Masterpiece", W: 384, H: 682, fps: FPS, bpm: 120, durationFrames: DURATION, kind: "drawing", holds: [[540, 600]] },
  assets: { images: { bee: "data:image/png;base64," } },
  shots: [{ id: "timelapse", start: 0, end: DURATION, draw: drawBeeDetailed }],
};
